class N:
    def __init__(s, k): s.k, s.l, s.r = k, None, None
def ins(t, k):
    if t is None: return N(k)
    if k < t.k: t.l = ins(t.l, k)
    else: t.r = ins(t.r, k)
    return t
def post(t, o):
    if t: post(t.l, o); post(t.r, o); o.append(t.k)
    return o
t = None
for k in [40, 61, 25, 33, 10, 70, 52, 5, 36, 18, 66, 28]: t = ins(t, k)
print(post(t, [])[6])   # 25
